import{_ as a,o as e,a as l,b as i}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul Tiling类","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling"},{"text":"SetMatmulConfigParams","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetMatmulConfigParams"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetMatmulConfigParams.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetMatmulConfigParams.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788515292000}'),n={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetMatmulConfigParams.md"};function r(s,t,d,h,m,o){return e(),l("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>SetMatmulConfigParams</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>在计算Tiling时，用于自定义设置<a href="#table9646134355611">表1</a>中的MatmulConfig参数。本接口中配置的参数对应的功能在Tiling与核函数（Kernel）中需要保持一致，所以本接口中的参数取值，需要与核函数（Kernel）侧对应的MatmulConfig参数值保持一致，详细MatmulConfig参数请见<a href="../Matmul_Kernel/MatmulConfig.html#matmulconfig-params">表2</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>void SetMatmulConfigParams(int32_t mmConfigTypeIn = 1, bool enableL1CacheUBIn = false, ScheduleType scheduleTypeIn = ScheduleType::INNER_PRODUCT, MatrixTraverse traverseIn = MatrixTraverse::NOSET, bool enVecND2NZIn = false)
</code></pre></div><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>void SetMatmulConfigParams(const MatmulConfigParams&amp; configParams)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><p><span id="table9646134355611"></span></p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mmConfigTypeIn</td><td>输入</td><td>设置Matmul的模板类型，需要与Matmul对象创建的模板一致，当前只支持配置为0或1。<br>0：代表Norm模板<br>1：代表MDL模板，默认值为1</td></tr><tr><td>enableL1CacheUBIn</td><td>输入</td><td>配置是否开启L1缓存Unified Buffer（UB）计算块；推荐开启场景：MTE3和MTE2流水串行较多的场景。<br>false：不开启L1缓存UB计算块，默认值为false<br>true：开启L1缓存UB计算块<span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span></td></tr><tr><td>scheduleTypeIn</td><td>输入</td><td>配置Matmul数据搬运模式。参数取值如下：<br>ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运<br>ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运<br>ScheduleType::N_BUFFER_33：<a href="../Matmul_Kernel/MatmulPolicy.html#li194081238103913">NBuffer33</a>模板的数据搬运模式，MTE2每次搬运A矩阵的1x3个基本块，直至A矩阵所有3x3个基本块全载在L1 Buffer中</td></tr><tr><td>traverseIn</td><td>输入</td><td>Matmul做矩阵运算的循环迭代顺序，即一次迭代计算出[baseM, baseN]大小的C矩阵分片后，自动偏移到下一次迭代输出的C矩阵位置的偏移顺序。参数取值如下：<br><br>NOSET：0，当前无效。<br><br>FIRSTM：先往M轴方向偏移再往N轴方向偏移。<br><br>FIRSTN：先往N轴方向偏移再往M轴方向偏移。</td></tr><tr><td>enVecND2NZIn</td><td>输入</td><td>是否开启ND2NZ。</td></tr><tr><td>configParams</td><td>输入</td><td>config相关参数，类型为MatmulConfigParams，结构体具体定义如下方代码所示。其中的参数说明请参考<a href="#table15780447181917">表2</a>。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>struct MatmulConfigParams {
    int32_t mmConfigType;
    bool enableL1CacheUB;
    ScheduleType scheduleType;
    MatrixTraverse traverse;
    bool enVecND2NZ;
    MatmulConfigParams(
        int32_t mmConfigTypeIn = 1, bool enableL1CacheUBIn = false,
        ScheduleType scheduleTypeIn = ScheduleType::INNER_PRODUCT, MatrixTraverse traverseIn = MatrixTraverse::NOSET,
        bool enVecND2NZIn = false)
    {
        mmConfigType = mmConfigTypeIn;
        enableL1CacheUB = enableL1CacheUBIn;
        scheduleType = scheduleTypeIn;
        traverse = traverseIn;
        enVecND2NZ = enVecND2NZIn;
    }
};
</code></pre></div><p><strong>表2</strong> MatmulConfigParams结构体内参数说明</p><p><span id="table15780447181917"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mmConfigType</td><td>设置Matmul的模板类型，需要与Matmul对象创建的模板一致，当前只支持配置为0或1。<br>0：代表Norm模板<br>1：代表MDL模板，默认值为1</td></tr><tr><td>enableL1CacheUB</td><td>配置是否开启L1缓存UB计算块；推荐开启场景：MTE3和MTE2流水串行较多的场景。<br>false：不开启L1缓存UB计算块，默认值为false<br>true：开启L1缓存UB计算块</td></tr><tr><td>scheduleType</td><td>配置Matmul数据搬运模式。参数取值如下：<br>ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运<br>ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运<br>ScheduleType::N_BUFFER_33：<a href="../Matmul_Kernel/MatmulPolicy.html#li194081238103913">NBuffer33</a>模板的数据搬运模式，MTE2每次搬运A矩阵的1x3个基本块，直至A矩阵所有3x3个基本块全载在L1 Buffer中</td></tr><tr><td>traverse</td><td>Matmul做矩阵运算的循环迭代顺序，即一次迭代计算出[baseM, baseN]大小的C矩阵分片后，自动偏移到下一次迭代输出的C矩阵位置的偏移顺序。参数取值如下：<br><br>NOSET：0，当前无效。<br><br>FIRSTM：先往M轴方向偏移再往N轴方向偏移。<br><br>FIRSTN：先往N轴方向偏移再往M轴方向偏移。</td></tr><tr><td>enVecND2NZ</td><td>是否开启ND2NZ</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口必须在<a href="GetTiling.html">GetTiling</a>接口前调用。</li><li>若Matmul对象使用NBuffer33模板策略，即MatmulPolicy为<a href="../Matmul_Kernel/MatmulPolicy.html#li194081238103913">NBuffer33MatmulPolicy</a>，则在调用<a href="GetTiling.html">GetTiling</a>接口生成Tiling参数前，必须通过本接口将scheduleTypeIn参数设置为ScheduleType::N_BUFFER_33，以启用NBuffer33模板策略的Tiling生成逻辑。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MatmulApiTiling tiling(ascendcPlatform);
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetShape(1024, 1024, 1024);
tiling.SetOrgShape(1024, 1024, 1024);
tiling.SetBias(true);
tiling.SetBufferSpace(-1, -1, -1);
tiling.SetMatmulConfigParams(0); // 额外设置
// matmul_tiling::MatmulConfigParams configParams =
//     {1, false, matmul_tiling::ScheduleType::OUTER_PRODUCT, matmul_tiling::MatrixTraverse::FIRSTM};
// tiling.SetMatmulConfigParams(configParams);
optiling::TCubeTiling tilingData;
int ret = tiling.GetTiling(tilingData);
</code></pre></div></article></div>`,1)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
